WITH latest_match AS (SELECT s.id, s.email, s.country, s.signup_date, s.credit_limit, x.account_opened_date, x.account_balance FROM customers s LEFT JOIN LATERAL (SELECT c.opened_date AS account_opened_date, c.balance AS account_balance FROM accounts c WHERE c.customer_id = s.id ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) x ON TRUE), with_last AS (SELECT s.*, top1.account_balance_2, top1.account_status FROM latest_match s LEFT JOIN LATERAL (SELECT c.balance AS account_balance_2, c.status AS account_status FROM accounts c WHERE c.customer_id = s.id ORDER BY c.balance DESC, c.id DESC LIMIT 1) top1 ON TRUE), metrics AS (SELECT id, email, country, credit_limit, account_opened_date, account_balance, CUME_DIST() OVER (ORDER BY account_balance_2 DESC NULLS LAST) AS account_balance_2_cume_dist, ROW_NUMBER() OVER (PARTITION BY account_status, country ORDER BY credit_limit, id) AS seq_no, LAG(account_balance_2, 1) OVER (PARTITION BY country ORDER BY account_opened_date, id) AS prev_account_balance_2, LAST_VALUE(account_status) IGNORE NULLS OVER (PARTITION BY account_status, country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_account_status FROM with_last), not_flagged AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM sessions x WHERE x.customer_id = s.id AND x.started_at <= s.account_opened_date)), with_last_customers AS (SELECT s.id, s.credit_limit, s.account_opened_date, s.account_balance_2_cume_dist, s.seq_no, s.prev_account_balance_2, top1.session_country FROM not_flagged s JOIN LATERAL (SELECT c.country AS session_country FROM sessions c WHERE c.customer_id = s.id ORDER BY c.started_at DESC, c.id DESC LIMIT 1) top1 ON TRUE), eligible AS (SELECT s.* FROM with_last_customers s WHERE EXISTS (SELECT 1 FROM subscriptions ch WHERE ch.customer_id = s.id AND ch.end_date < '2025-10-24')), report AS (SELECT id, credit_limit, seq_no, session_country FROM eligible ORDER BY seq_no, session_country) SELECT id, credit_limit, seq_no, session_country, CASE WHEN session_country RLIKE '^(DE|UK)$' THEN 'EXTENDED' WHEN session_country RLIKE '^(TH|US)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS session_country_zone FROM report ORDER BY credit_limit NULLS FIRST, id DESC;
